```css
/* ==============================
   GENERAL STYLES
   ============================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: Arial, Helvetica, sans-serif;
    line-height: 1.6;
    color: #1f2937;
    background-color: #ffffff;
}

.container {
    width: min(1100px, 92%);
    margin: 0 auto;
}

a {
    text-decoration: none;
}

img {
    display: block;
    width: 100%;
}


/* ==============================
   HEADER
   ============================== */

.header {
    background-color: #ffffff;
    border-bottom: 1px solid #e5e7eb;
    position: sticky;
    top: 0;
    z-index: 100;
}

.header .container {
    min-height: 72px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
}

.brand {
    font-size: 1.6rem;
    font-weight: 800;
    color: #166534;
}

.navigation {
    display: flex;
    align-items: center;
    gap: 28px;
}

.navigation a {
    color: #374151;
    font-weight: 600;
    transition: color 0.3s ease;
}

.navigation a:hover {
    color: #166534;
}


/* ==============================
   KEYBOARD FOCUS
   ============================== */

a:focus-visible,
summary:focus-visible {
    outline: 3px solid #f59e0b;
    outline-offset: 4px;
    border-radius: 4px;
}


/* ==============================
   HERO
   ============================== */

.hero {
    background-color: #f0fdf4;
    padding: 80px 0;
}

.hero-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 60px;
}

.eyebrow {
    color: #15803d;
    font-size: 0.85rem;
    font-weight: 800;
    letter-spacing: 1.5px;
    margin-bottom: 12px;
}

.hero h1 {
    font-size: clamp(2.3rem, 5vw, 4rem);
    line-height: 1.1;
    margin-bottom: 22px;
    color: #14532d;
}

.hero-text > p:not(.eyebrow) {
    font-size: 1.1rem;
    color: #4b5563;
    max-width: 550px;
    margin-bottom: 30px;
}

.button {
    display: inline-block;
    background-color: #15803d;
    color: white;
    padding: 13px 24px;
    border-radius: 8px;
    font-weight: 700;
    transition: transform 0.3s ease, background-color 0.3s ease;
}

.button:hover {
    background-color: #166534;
    transform: translateY(-3px);
}

.hero-image img {
    height: 400px;
    object-fit: cover;
    border-radius: 20px;
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.12);
}


/* ==============================
   COURSES
   ============================== */

.courses {
    padding: 80px 0;
}

.section-heading {
    text-align: center;
    max-width: 650px;
    margin: 0 auto 45px;
}

.section-heading h2,
.about h2 {
    font-size: 2.2rem;
    color: #14532d;
    margin-bottom: 12px;
}

.section-heading > p:last-child {
    color: #6b7280;
}


/* ==============================
   COURSE CARDS
   ============================== */

.course-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 25px;
}

.course-card {
    background-color: white;
    border: 1px solid #e5e7eb;
    border-radius: 16px;
    overflow: hidden;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.07);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.course-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 16px 35px rgba(0, 0, 0, 0.12);
}

.course-card > img {
    height: 220px;
    object-fit: cover;
}

.card-content {
    padding: 24px;
}

.category {
    display: inline-block;
    background-color: #dcfce7;
    color: #166534;
    font-size: 0.8rem;
    font-weight: 800;
    padding: 5px 10px;
    border-radius: 20px;
    margin-bottom: 12px;
}

.course-card h3 {
    font-size: 1.4rem;
    color: #111827;
    margin-bottom: 10px;
}

.course-card p {
    color: #6b7280;
    margin-bottom: 18px;
}

details {
    border-top: 1px solid #e5e7eb;
    padding-top: 15px;
}

summary {
    cursor: pointer;
    color: #15803d;
    font-weight: 700;
}

details ul {
    margin-top: 12px;
    padding-left: 20px;
    color: #4b5563;
}


/* ==============================
   ABOUT
   ============================== */

.about {
    background-color: #f9fafb;
    padding: 80px 0;
}

.about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: start;
}

.about p {
    color: #4b5563;
    margin-bottom: 15px;
}


/* ==============================
   FOOTER
   ============================== */

.footer {
    background-color: #14532d;
    color: white;
    padding-top: 55px;
}

.footer-content {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 50px;
    padding-bottom: 45px;
}

.footer h2,
.footer h3 {
    margin-bottom: 15px;
}

.footer p {
    color: #d1fae5;
    margin-bottom: 8px;
}

.footer a {
    display: block;
    color: #d1fae5;
    margin-bottom: 8px;
}

.footer a:hover {
    color: white;
    text-decoration: underline;
}

.copyright {
    border-top: 1px solid rgba(255, 255, 255, 0.2);
    text-align: center;
    padding: 20px;
}

.copyright p {
    margin: 0;
}


/* ==============================
   TABLET
   ============================== */

@media (max-width: 900px) {

    .hero-content {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .hero-text {
        text-align: center;
    }

    .hero-text > p:not(.eyebrow) {
        margin-left: auto;
        margin-right: auto;
    }

    .course-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .about-content {
        grid-template-columns: 1fr;
        gap: 25px;
    }

    .footer-content {
        grid-template-columns: 1fr 1fr;
    }
}


/* ==============================
   PHONE
   ============================== */

@media (max-width: 600px) {

    .header .container {
        flex-direction: column;
        justify-content: center;
        padding: 18px 0;
        gap: 15px;
    }

    .navigation {
        gap: 15px;
        flex-wrap: wrap;
        justify-content: center;
    }

    .navigation a {
        font-size: 0.9rem;
    }

    .hero {
        padding: 55px 0;
    }

    .hero h1 {
        font-size: 2.3rem;
    }

    .hero-image img {
        height: 280px;
    }

    .courses,
    .about {
        padding: 55px 0;
    }

    .section-heading h2,
    .about h2 {
        font-size: 1.8rem;
    }

    .course-grid {
        grid-template-columns: 1fr;
    }

    .course-card > img {
        height: 210px;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: 30px;
    }
}
