    .hero-image img {
        height: 280px;
    }

    .courses,
    .about {
        padding: 55px 0;
    }

    .section-heading h2,
    .about h2 {
        font-size: 1.8rem;
    }

    .course-grid {
        grid-template-columns: 1fr;
    }

    .course-card > img {
        height: 210px;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: 30px;
    }
}
